// QR Decomposition with Modified Gram-Schmidt
//
// This implementation keeps the mathematical algorithm identical to the
// original PolyBench version, but restructures the inner loops:
//
//  - All loops over data dimensions ('i', 'j') are expressed using Noarr
//    traversers (`for_each` / `for_dims`), as requested.
//  - For each k, we compute all R[k][j] (j > k) *simultaneously* using a
//    temporary row buffer `r_temp`. This avoids re-reading Q[:,k] for every
//    j and improves data locality:
//        * each Q[i][k] is loaded once per i and reused for all j > k
//        * A is traversed in 2D blocks with good cache behavior
//  - Accumulations use `std::fma` to encourage fused multiply-add.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	const std::size_t m = A | get_length<'i'>(); // not used explicitly, but documents layout
	const std::size_t n = A | get_length<'j'>();

	(void)m; // traversal takes care of bounds

	// Workspace for one row of R (R[k][*]). Size N is small compared to A/Q.
	std::vector<num_t> r_temp(n);

	#pragma scop
	for (std::size_t k = 0; k < n; k++) {

		// k-th column views of A and Q (A[:, k], Q[:, k])
		auto A_col_k = A ^ noarr::fix<'j'>(k);
		auto Q_col_k = Q ^ noarr::fix<'j'>(k);

		// ---------------------------------------------------------------------
		// 1) Compute the norm of column k: nrm = sum_i A[i][k]^2
		// ---------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		noarr::traverser(A_col_k).for_each([&](auto state_i) {
			const num_t a_ik = A_col_k[state_i];
			// Use FMA to accumulate with potentially better precision/performance
			nrm = std::fma(a_ik, a_ik, nrm);
		});

		// ---------------------------------------------------------------------
		// 2) Normalize column k: Q[:,k] = A[:,k] / R[k][k]
		// ---------------------------------------------------------------------
		const num_t r_kk = std::sqrt(nrm);
		const num_t inv_r_kk = (num_t)1.0 / r_kk; // replace many divides with one reciprocal

		R[noarr::idx<'k', 'j'>(k, k)] = r_kk;

		noarr::traverser(A_col_k, Q_col_k).for_each([&](auto state_i) {
			Q_col_k[state_i] = A_col_k[state_i] * inv_r_kk;
		});

		// ---------------------------------------------------------------------
		// 3) Handle trailing columns j > k
		//
		// Original code (per k):
		//   for (j = k + 1; j < n; j++) {
		//     r_kj = 0;
		//     for (i = 0; i < m; i++)
		//       r_kj += Q[i][k] * A[i][j];
		//     R[k][j] = r_kj;
		//     for (i = 0; i < m; i++)
		//       A[i][j] -= Q[i][k] * r_kj;
		//   }
		//
		// We compute all r_kj (j > k) at once into r_temp, using a 2D traversal.
		// This reuses each Q[i][k] once for all j > k and improves cache use
		// on A, while preserving exact algebra.
		// ---------------------------------------------------------------------
		const std::size_t j_start = k + 1;
		if (j_start >= n)
			continue; // nothing left to process in this k

		const std::size_t tail_cols = n - j_start;

		// r_tail[j_local] corresponds to R[k][j_start + j_local]
		num_t *const r_tail = r_temp.data() + j_start;

		// Zero only the relevant tail part; positions <= k are never read.
		std::fill(r_tail, r_tail + tail_cols, (num_t)0.0);

		// View of all trailing columns A[:, j>k]
		auto A_tail = A ^ noarr::slice<'j'>(j_start, tail_cols);

		// 3a) Compute r_kj = sum_i Q[i][k] * A[i][j] for all j > k.
		// Outer loop over 'i', inner loop over 'j' (row-major friendly).
		noarr::traverser(A_tail, Q_col_k).template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed; remaining dimension is 'j' over the tail
			const num_t q_ik = Q_col_k[trav_i]; // Q[i][k], constant for this row

			trav_i.for_each([&](auto state_ij) {
				const std::size_t j_local = noarr::get_index<'j'>(state_ij); // 0..tail_cols-1
				const num_t a_ij = A_tail[state_ij];

				// r_tail[j_local] += q_ik * a_ij;
				r_tail[j_local] = std::fma(q_ik, a_ij, r_tail[j_local]);
			});
		});

		// 3b) Store the accumulated R[k][j] for j > k from r_tail
		auto R_row_k_tail = R
			^ noarr::fix<'k'>(k)
			^ noarr::slice<'j'>(j_start, tail_cols); // dims: only 'j' (tail)

		noarr::traverser(R_row_k_tail).for_each([&](auto state_j_tail) {
			const std::size_t j_local = noarr::get_index<'j'>(state_j_tail);
			R_row_k_tail[state_j_tail] = r_tail[j_local];
		});

		// 3c) Rank-1 update: A[:, j>k] -= Q[:,k] * R[k,j]
		noarr::traverser(A_tail, Q_col_k).template for_dims<'i'>([&](auto trav_i) {
			const num_t q_ik = Q_col_k[trav_i]; // Q[i][k]

			trav_i.for_each([&](auto state_ij) {
				const std::size_t j_local = noarr::get_index<'j'>(state_ij);
				A_tail[state_ij] = A_tail[state_ij] - q_ik * r_tail[j_local];
			});
		});
	}
	#pragma endscop
}

} // namespace


