	// Outer loop over k implemented as a traversal over the 'k'
	// dimension of R. The order is 0 .. n-1, which matches the
	// classical Gram-Schmidt algorithm.
	traverser(R).template for_dims<'k'>([&](auto trav_k) {
		// trav_k has 'k' fixed; extract its state to get the k index
		auto state_k = trav_k.state(); // contains index_in<'k'>
		const std::size_t k = get_index<'k'>(state_k);

		// Create views of the k-th column of A and Q: A[:, k], Q[:, k].
		// With column-major layout (i contiguous), these are contiguous
		// 1D vectors in memory, which is ideal for the inner products
		// and scaling operations below.
		auto A_col_k = A ^ fix<'j'>(k);
		auto Q_col_k = Q ^ fix<'j'>(k);

		// nrm = sum_i A[i][k]^2
		num_t nrm = (num_t)0.0;
		traverser(A_col_k).for_each([&](auto s_i) {
			const num_t a_ik = A_col_k[s_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		const num_t r_kk = std::sqrt(nrm);

		// Construct the state for (k, k) in R using the current 'k'
		// and setting 'j' = k.
		auto diag_state = state_k.template with<index_in<'j'>>(k);
		R[diag_state] = r_kk;

		// Q[i][k] = A[i][k] / R[k][k]  for all i
		traverser(A_col_k, Q_col_k).for_each([&](auto s_i) {
			Q_col_k[s_i] = A_col_k[s_i] / r_kk;
		});

		// For the last k, there are no trailing columns j > k.
		if (k + 1 >= n)
			return;

		const std::size_t trailing_cols = n - (k + 1);

		// Create a 1D view of the trailing part of the k-th row of R:
		//   R_row_tail corresponds to R[k][j] for j in [k+1, n)
		//
		// This is done structurally using:
		//   - fix<'k'>(k):    select row k
		//   - slice<'j'>(...): limit j to (k+1 .. n-1)
		auto R_row_tail = R
			^ fix<'k'>(k)
			^ slice<'j'>(k + 1, trailing_cols);

		// Iterate over the trailing columns j > k
		traverser(R_row_tail).for_each([&](auto s_j_tail) {
			// s_j_tail has only 'j' index (k is fixed by the view)
			const std::size_t j = get_index<'j'>(s_j_tail);

			// View of column j of A: A[:, j]
			auto A_col_j = A ^ fix<'j'>(j);

			// R[k][j] = sum_i Q[i][k] * A[i][j]
			num_t r_kj = (num_t)0.0;
			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				r_kj += Q_col_k[s_i] * A_col_j[s_i];
			});

			// Store R[k][j] via the row tail view
			R_row_tail[s_j_tail] = r_kj;

			// A[i][j] -= Q[i][k] * R[k][j]  for all i
			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				A_col_j[s_i] = A_col_j[s_i] - Q_col_k[s_i] * r_kj;
			});
		});
	});
