// Main computational kernel --------------------------------------------------
// QR Decomposition with Modified Gram-Schmidt
//
// The algorithm is column-oriented in j (k is the current column). By making
// 'i' the inner (contiguous) dimension for A and Q, column views obtained by
// fix<'j'>(k) become 1D contiguous vectors, which improves cache locality and
// allows the compiler to better vectorize the inner products.
//
// All data-dependent loops (over i, j, k) are expressed using Noarr traversers
// and for_dims, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	auto m = A | get_length<'i'>();
	auto n = A | get_length<'j'>();

	(void)m; // m is not explicitly needed, traversal takes care of bounds

	#pragma scop
	// Outer loop over k (current column). We drive it through R, which has
	// dimensions 'k' x 'j'. This keeps the algorithm sequential in k while
	// still using Noarr traversal constructs.
	noarr::traverser(R).template for_dims<'k'>([&](auto k_trav) {
		// Current column index k
		auto k_state = k_trav.state();
		std::size_t k = noarr::get_index<'k'>(k_state);

		// ---------------------------------------------------------------------
		// 1) Compute the 2-norm of column k of A: nrm = sum_i A[i][k]^2
		//    and store the result into R[k][k] = sqrt(nrm).
		// ---------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		// k-th column views of A and Q (A[:, k], Q[:, k])
		auto A_col_k = A ^ noarr::fix<'j'>(k);
		auto Q_col_k = Q ^ noarr::fix<'j'>(k);

		noarr::traverser(A_col_k).for_each([&](auto state_i) {
			num_t a_ik = A_col_k[state_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[noarr::idx<'k', 'j'>(k, k)] = r_kk;

		// ---------------------------------------------------------------------
		// 2) Normalize column k of A into Q: Q[i][k] = A[i][k] / R[k][k]
		// ---------------------------------------------------------------------
		noarr::traverser(A_col_k, Q_col_k).for_each([&](auto state_i) {
			Q_col_k[state_i] = A_col_k[state_i] / r_kk;
		});

		// If this is the last column, there is nothing left to orthogonalize
		// against it.
		if (k + 1 >= n)
			return;

		// ---------------------------------------------------------------------
		// 3) For all j > k:
		//      R[k][j] = sum_i Q[i][k] * A[i][j]
		//      A[i][j] = A[i][j] - Q[i][k] * R[k][j]
		//
		//    We realize the j-loop via a sliced traverser over R's 'j' dim:
		//    j in [k+1, n). This keeps the access pattern row-wise in R
