		// ---------------------------------------------------------------------
		auto tail_trav = k_trav.order(noarr::slice<'j'>(k + 1, n - (k + 1)));

		tail_trav.template for_dims<'j'>([&](auto kj_trav) {
			auto kj_state = kj_trav.state();
			std::size_t j = noarr::get_index<'j'>(kj_state);

			// j-th column view of A: A[:, j]
			auto A_col_j = A ^ noarr::fix<'j'>(j);

			// Accumulate R[k][j] = sum_i Q[i][k] * A[i][j]
			num_t r_kj = (num_t)0.0;

