// QR Decomposition with Modified Gram-Schmidt
//
// Optimized version:
// - All loop nests are expressed via noarr::traverser / for_dims.
// - Outer loop over k uses traverser(R).for_dims<'k'>.
// - Inner triangular loop over j uses a row view of R with slice<'j'>(k+1, ...).
// - Division by R[k][k] when forming Q is turned into multiplication by its
//   reciprocal to reduce the cost of the operation.
// - Column views are expressed once per (k,j) using noarr::fix, which is
//   a light-weight view change and preserves the original memory layout.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	auto m = A | get_length<'i'>();
	auto n = A | get_length<'j'>();

	(void)m; // traversal takes care of bounds, m is not needed explicitly

	#pragma scop
	// Traverse the outer "k" dimension of R: k = 0 .. n-1
	traverser(R).template for_dims<'k'>([&](auto trav_k) {
		// Extract current k index from traverser's fixed state
		auto state_k = trav_k.state();
		std::size_t k = get_index<'k'>(state_k);

		// k-th column views of A and Q: A[:, k], Q[:, k]
		auto A_col_k = A ^ fix<'j'>(k);
		auto Q_col_k = Q ^ fix<'j'>(k);

		// --------------------------------------------------------------
		// nrm = sum_i A[i][k]^2
		// --------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		traverser(A_col_k).for_each([&](auto state_i) {
			num_t a_ik = A_col_k[state_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[idx<'k', 'j'>(k, k)] = r_kk;

		// Precompute reciprocal of R[k][k] to replace division with multiplication
		num_t inv_r_kk = (num_t)1.0 / r_kk;

		// --------------------------------------------------------------
		// Q[:, k] = A[:, k] / R[k][k]
		// --------------------------------------------------------------
		traverser(A_col_k, Q_col_k).for_each([&](auto state_i) {
			Q_col_k[state_i] = A_col_k[state_i] * inv_r_kk;
		});

		// --------------------------------------------------------------
		// Inner triangular loop over j: for (j = k+1; j < n; ++j)
		// Implemented as a traversal of R's row k, sliced to j > k.
		// --------------------------------------------------------------
		auto R_row_k = R ^ fix<'k'>(k);

		// Restrict j to (k+1 .. n-1) using slice(start, length)
		// start  = k+1
		// length = n - (k+1)
		auto j_slice = slice<'j'>(k + 1, n - (k + 1));

		traverser(R_row_k)
			.order(j_slice)
			.template for_dims<'j'>([&](auto trav_j) {
				// Current column index j > k
				auto state_j = trav_j.state();
				std::size_t j = get_index<'j'>(state_j);

				// j-th column view of A: A[:, j]
				auto A_col_j = A ^ fix<'j'>(j);

				// ------------------------------------------------------
				// R[k][j] = sum_i Q[i][k] * A[i][j]
				// ------------------------------------------------------
				num_t r_kj = (num_t)0.0;

				// We traverse both Q_col_k and A_col_j along 'i'.
				traverser(Q_col_k, A_col_j).for_each([&](auto state_i) {
					r_kj += Q_col_k[state_i] * A_col_j[state_i];
				});

				// Store R[k][j] into the fixed row view
				R_row_k[state_j] = r_kj;

				// ------------------------------------------------------
				// A[:, j] = A[:, j] - Q[:, k] * R[k][j]
				// Use an FMA-friendly form: A += Q * (-r_kj)
				// ------------------------------------------------------
				num_t minus_r_kj = -r_kj;

				traverser(Q_col_k, A_col_j).for_each([&](auto state_i) {
					A_col_j[state_i] += Q_col_k[state_i] * minus_r_kj;
